class SpellListType(Enum):
    ARTIFICER = "Artificer"
    BARD = "Bard"
    CLERIC = "Cleric"
    DRUID = "Druid"
    PALADIN = "Paladin"
    RANGER = "Ranger"
    SORCERER = "Sorcerer"
    WARLOCK = "Warlock"
    WIZARD = "Wizard"


CLASS_SPELL_LISTS: dict[ClassType, SpellListType] = {
    ClassType.ARTIFICER: SpellListType.ARTIFICER,
    ClassType.BARD: SpellListType.BARD,
    ClassType.CLERIC: SpellListType.CLERIC,
    ClassType.DRUID: SpellListType.DRUID,
    ClassType.PALADIN: SpellListType.PALADIN,
    ClassType.RANGER: SpellListType.RANGER,
    ClassType.SORCERER: SpellListType.SORCERER,
    ClassType.WARLOCK: SpellListType.WARLOCK,
    ClassType.WIZARD: SpellListType.WIZARD,
}


def class_spell_list(class_type: ClassType) -> SpellListType | None:
    return CLASS_SPELL_LISTS.get(class_type)


def spell_effect_dice(
    dice_count: int,
    dice_type: DiceType,
    *,
    static_bonus: int = 0,
    bonus_ability: AbilityType | None = None,
    bonus_spellcasting_ability: bool = False,
) -> SpellEffectDice:
    return SpellEffectDice(
        diceCount=dice_count,
        diceType=dice_type,
        staticBonus=static_bonus,
        bonusAbility=bonus_ability,
        bonusSpellcastingAbility=bonus_spellcasting_ability,
    )


def spell_save(
    ability: AbilityType,
    outcome: SpellSaveOutcome = SpellSaveOutcome.NEGATES,
    *,
    repeat: SpellEffectTrigger | None = None,
) -> SpellSavingThrow:
    return SpellSavingThrow(ability=ability, outcome=outcome, repeat=repeat)


def spell_scaling(
    scaling_type: SpellScalingType,
    *,
    dice_count: int | None = None,
    dice_type: DiceType | None = None,
    static_bonus: int = 0,
    instances: int = 0,
    interval: int = 1,
    description: str = "",
) -> SpellScaling:
    additional_dice = None
    if dice_count is not None and dice_type is not None:
        additional_dice = spell_effect_dice(dice_count, dice_type)
    return SpellScaling(
        scalingType=scaling_type,
        additionalDice=additional_dice,
        additionalStaticBonus=static_bonus,
        additionalInstances=instances,
        interval=interval,
        description=description,
    )


def spell_damage_effect(
    dice_count: int,
    dice_type: DiceType,
    damage_type: DamageType,
    *,
    static_bonus: int = 0,
    bonus_ability: AbilityType | None = None,
    bonus_spellcasting_ability: bool = False,
    trigger: SpellEffectTrigger = SpellEffectTrigger.ON_CAST,
    target: SpellEffectTarget = SpellEffectTarget.TARGET,
    attack: SpellAttackType = SpellAttackType.NONE,
    saving_throw: SpellSavingThrow | None = None,
    scaling: list[SpellScaling] | None = None,
    instances: int = 1,
    instance_label: str = "",
    action_label: str = "",
    description: str = "",
) -> SpellEffect:
    return SpellEffect(
        kind=SpellEffectKind.DAMAGE,
        trigger=trigger,
        target=target,
        attack=attack,
        savingThrow=saving_throw,
        damage=SpellDamageEffect(
            spell_effect_dice(
                dice_count,
                dice_type,
                static_bonus=static_bonus,
                bonus_ability=bonus_ability,
                bonus_spellcasting_ability=bonus_spellcasting_ability,
            ),
            damage_type,
        ),
        scaling=scaling,
        instances=instances,
        instanceLabel=instance_label,
        actionLabel=action_label,
        description=description,
    )


def spell_healing_effect(
    dice_count: int,
    dice_type: DiceType,
    *,
    static_bonus: int = 0,
    bonus_ability: AbilityType | None = None,
    bonus_spellcasting_ability: bool = False,
    trigger: SpellEffectTrigger = SpellEffectTrigger.ON_CAST,
    target: SpellEffectTarget = SpellEffectTarget.TARGET,
    scaling: list[SpellScaling] | None = None,
    description: str = "",
) -> SpellEffect:
    return SpellEffect(
        kind=SpellEffectKind.HEALING,
        trigger=trigger,
        target=target,
        healing=SpellHealingEffect(
            spell_effect_dice(
                dice_count,
                dice_type,
                static_bonus=static_bonus,
                bonus_ability=bonus_ability,
                bonus_spellcasting_ability=bonus_spellcasting_ability,
            )
        ),
        scaling=scaling,
        description=description,
    )


def spell_temporary_hit_points_effect(
    dice_count: int,
    dice_type: DiceType,
    *,
    static_bonus: int = 0,
    bonus_ability: AbilityType | None = None,
    trigger: SpellEffectTrigger = SpellEffectTrigger.ON_CAST,
    target: SpellEffectTarget = SpellEffectTarget.TARGET,
    scaling: list[SpellScaling] | None = None,
    description: str = "",
) -> SpellEffect:
    return SpellEffect(
        kind=SpellEffectKind.TEMPORARY_HIT_POINTS,
        trigger=trigger,
        target=target,
        temporaryHitPoints=spell_effect_dice(
            dice_count,
            dice_type,
            static_bonus=static_bonus,
            bonus_ability=bonus_ability,
        ),
        scaling=scaling,
        description=description,
    )


def spell_condition_effect(
    condition: ConditionType,
    *,
    duration: ConditionDuration = ConditionDuration.MANUAL,
    save_ends: bool = False,
    removal_trigger: ConditionRemovalTrigger | None = None,
    removal_advantage: bool = False,
    trigger: SpellEffectTrigger = SpellEffectTrigger.ON_FAILED_SAVE,
    target: SpellEffectTarget = SpellEffectTarget.TARGET,
    saving_throw: SpellSavingThrow | None = None,
    scaling: list[SpellScaling] | None = None,
    description: str = "",
) -> SpellEffect:
    return SpellEffect(
        kind=SpellEffectKind.CONDITION,
        trigger=trigger,
        target=target,
        savingThrow=saving_throw,
        conditions=[
            SpellConditionEffect(
                condition=condition,
                duration=duration,
                saveEnds=save_ends,
                removalTrigger=removal_trigger,
                removalAdvantage=removal_advantage,
            )
        ],
        scaling=scaling,
        description=description,
    )


@dataclass(frozen=True)
class SpellCatalogMetadata:
    spellId: SpellId
    spellLists: tuple[SpellListType, ...]
    url: str
    castingDuration: SpellDuration | None = None
    triggered: bool = False
    material: bool = False
    materialCost: bool = False
    materialConsumed: bool = False


def spell_catalog() -> dict[SpellId, SpellEntry]:
    return {spell_id: clone_spell_entry(spell) for spell_id, spell in SPELL_CATALOG.items()}


def spell_entry(value: str | SpellId) -> SpellEntry | None:
    spell_id = value if isinstance(value, SpellId) else enum_value(SpellId, value)
    spell = SPELL_CATALOG.get(spell_id)
    return clone_spell_entry(spell) if spell is not None else None


def spell_metadata(value: str | SpellId) -> SpellCatalogMetadata | None:
    spell_id = value if isinstance(value, SpellId) else enum_value(SpellId, value)
    return SPELL_METADATA.get(spell_id)


def spell_metadata_for_list(
    spell_list: SpellListType,
    *,
    maximum_level: int | None = None,
    exact_level: int | None = None,
    schools: set[SpellSchool] | None = None,
) -> list[SpellCatalogMetadata]:
    return [
        metadata
        for spell_id, metadata in SPELL_METADATA.items()
        if spell_list in metadata.spellLists
        and (maximum_level is None or SPELL_CATALOG[spell_id].level <= maximum_level)
        and (exact_level is None or SPELL_CATALOG[spell_id].level == exact_level)
        and (schools is None or SPELL_CATALOG[spell_id].school in schools)
    ]


def spell_entries_for_list(
    spell_list: SpellListType,
    *,
    maximum_level: int | None = None,
    exact_level: int | None = None,
    schools: set[SpellSchool] | None = None,
    source: SpellSource = SpellSource.WIZARD,
    casting_ability: AbilityType = AbilityType.INTELLIGENCE,
) -> list[SpellEntry]:
    return [
        normalized_spell_entry(SPELL_CATALOG[metadata.spellId], source=source, casting_ability=casting_ability)
        for metadata in spell_metadata_for_list(
            spell_list,
            maximum_level=maximum_level,
            exact_level=exact_level,
            schools=schools,
        )
    ]


def spell_entry_for_list(
    value: str | SpellId,
    spell_list: SpellListType,
    *,
    source: SpellSource = SpellSource.WIZARD,
    casting_ability: AbilityType = AbilityType.INTELLIGENCE,
) -> SpellEntry | None:
    spell = spell_entry(value)
    metadata = spell_metadata(value)
    if spell is None or metadata is None or spell_list not in metadata.spellLists:
        return None
    return normalized_spell_entry(spell, source=source, casting_ability=casting_ability)


def artificer_spell_entry(value: str | SpellId, *, casting_ability: AbilityType = AbilityType.INTELLIGENCE) -> SpellEntry | None:
    return spell_entry_for_list(value, SpellListType.ARTIFICER, source=SpellSource.ARTIFICER, casting_ability=casting_ability)


